<pre><code> Assembly a = Assembly.LoadFrom("WindowsApplication1.exe");
        Form frm = a.CreateInstance("WindowsApplication1.FormB") as Form;
        frm.MdiParent = this;
        frm.Show();
</code></pre>", "<h2>Example</h2>

<pre><code>$dt = time();   // today... or use $dt = strtotime('2010-04-20'); to set custom start date.
$past_days = 7; // number of past days
$filesindir = dirTxt('your_dir');

for ($i=0; $i&lt;=$past_days; $i++) {
  $filename = 'abcd_' . date('Y_m_d', $dt) . '.txt';
  $files[] = $filename;
  $dt = strtotime('-1 day', $dt);
  } 

$files = array_intersect($filesindir, $files);

print_r($files);
</code></pre>

<h2>Output (might be like this, depends of $filesindir array)</h2>

<pre><code>Array
(
    [0] =&gt; abcd_2011_04_21.txt
    [1] =&gt; abcd_2011_04_20.txt
    [2] =&gt; abcd_2011_04_18.txt
    [3] =&gt; abcd_2011_04_15.txt
)
</code></pre>"]
